#!/bin/bash

# This script generates the baked ICU4X data used by Intl, in the crate
# src/brimstone_intl_data. See that crate's README.md.

set -e

CURRENT_DIR=$(cd "$(dirname "$0")" && pwd)
REPO_ROOT=$(cd "$CURRENT_DIR/.." && pwd)
CRATE_DIR="$REPO_ROOT/src/brimstone_intl_data"
DATA_DIR="$CRATE_DIR/src/data"

# This version must match the version of icu in Cargo.toml
ICU_VERSION="2.3.0"

# The locales Intl is built with, as a comma separated list. "en" must be part of the set: it is
# the locale Intl falls back to when nothing requested is available (see locale_negotiation.rs).
LOCALES="${LUCINAJS_INTL_LOCALES:-en,da,it}"

# Whether to bake the time zone *name* tables, the `TimezoneNames*` markers that
# `Intl.DateTimeFormat` needs for the `short`, `long`, `shortGeneric` and `longGeneric` values of
# `timeZoneName`. Off, the data only has the offset forms, and the engine says so rather than
# printing a name it has no data for. The choice is reported to the code as
# `brimstone_intl_data::TIME_ZONE_NAMES_ARE_BAKED`, which is why it is a variable of this script and
# not a Cargo feature: a Cargo feature cannot keep the code and the data it was generated with in
# step, and only the two of them together say whether a name can be printed.
TZ_NAMES="${LUCINAJS_INTL_TZ_NAMES:-1}"

# Install the datagen tool into a scratch cargo bin directory instead of ~/.cargo
CARGO_BIN_DIR="${CARGO_BIN_DIR:-${WORK_DIR:-$(mktemp -d)}/lucinanet/js-engine/cargo-bin}"

IFS=',' read -r -a LOCALE_ARRAY <<<"$LOCALES"

has_english=0
for locale in "${LOCALE_ARRAY[@]}"; do
  if [ "$locale" = "en" ]; then
    has_english=1
  fi
done

if [ "$has_english" -ne 1 ]; then
  echo "LUCINAJS_INTL_LOCALES must include \"en\", the Intl fallback locale, but is: $LOCALES" >&2
  exit 1
fi

case "$TZ_NAMES" in
  1 | true | yes)
    TZ_NAMES_BAKED=true
    MARKER_LIST="$CURRENT_DIR/intl_markers.txt"
    ;;
  0 | false | no)
    TZ_NAMES_BAKED=false
    # The name tables, which are the nine `TimezoneNames*V1` markers except
    # `TimezoneNamesEssentialsV1`: the essentials are CLDR's GMT offset formats, needed for the
    # `shortOffset` and `longOffset` forms whatever the build is asked for, so they stay in.
    #
    # `intl_markers.txt` is a bare list, one marker per line, and the datagen call below reads it
    # unquoted so that the names reach the tool as separate arguments. The filtered copy keeps that
    # shape. The scratch directory of this repo is `$WORK_DIR`; `mktemp` follows `TMPDIR`, which the
    # build jobs set.
    TMPDIR="${TMPDIR:-${WORK_DIR:-$(mktemp -d)}/tmp}"
    mkdir -p "$TMPDIR"
    MARKER_LIST=$(mktemp)
    grep -vE '^TimezoneNames(Cities|Generic|Locations|Specific|Standard)' "$CURRENT_DIR/intl_markers.txt" >"$MARKER_LIST"
    ;;
  *)
    echo "LUCINAJS_INTL_TZ_NAMES must be 1 or 0, but is: $TZ_NAMES" >&2
    exit 1
    ;;
esac

cargo install --version "$ICU_VERSION" --root "$CARGO_BIN_DIR" --features unstable icu4x-datagen

"$CARGO_BIN_DIR/bin/icu4x-datagen" \
  --markers $(cat "$MARKER_LIST") \
  --locales "${LOCALE_ARRAY[@]}" \
  --format baked \
  --out "$DATA_DIR" \
  --overwrite \
  --pretty \
  --use-separate-crates

# Write the locale set the data was generated for, so the engine can state it truthfully.
BUILT_IN_RS="$CRATE_DIR/src/built_in.rs"

{
  echo "// @generated by icu/generate_intl_data.sh. Do not edit."
  echo "// Regenerate with: LUCINAJS_INTL_LOCALES=<comma separated locales> LUCINAJS_INTL_TZ_NAMES=<1 or 0> icu/generate_intl_data.sh"
  echo ""
  echo "/// The locales for which the baked data in this crate was generated, sorted."
  echo -n "pub const BUILT_IN_LOCALES: &[&str] = &["

  first=1
  for locale in $(printf '%s\n' "${LOCALE_ARRAY[@]}" | sed '/^$/d' | sort -u); do
    if [ "$first" -eq 1 ]; then
      first=0
    else
      echo -n ", "
    fi
    echo -n "\"$locale\""
  done

  echo "];"
  echo ""
  echo "/// The locale Intl falls back to when none of the requested locales is built in."
  echo 'pub const DEFAULT_LOCALE: &str = "en";'
  echo ""
  echo "/// Whether the baked data of this crate includes the time zone *name* tables, the"
  echo "/// \`TimezoneNames*\` markers behind the \`short\`, \`long\`, \`shortGeneric\` and \`longGeneric\`"
  echo "/// values of \`Intl.DateTimeFormat\`'s \`timeZoneName\`. This is the second half of the pair that"
  echo "/// decides whether such a name can be printed; the first is whether the option was asked for."
  echo "pub const TIME_ZONE_NAMES_ARE_BAKED: bool = $TZ_NAMES_BAKED;"
} >"$BUILT_IN_RS"
